def flood(a, walls):
    H,W=a.shape
    vis=np.zeros_like(a,bool); q=deque()
    for i in range(H):
        for j in (0,W-1):
            if a[i,j]==0 and not walls[i,j] and not vis[i,j]: vis[i,j]=True;q.append((i,j))
    for j in range(W):
        for i in (0,H-1):
            if a[i,j]==0 and not walls[i,j] and not vis[i,j]: vis[i,j]=True;q.append((i,j))
    while q:
        i,j=q.popleft()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<H and 0<=nj<W and a[ni,nj]==0 and not walls[ni,nj] and not vis[ni,nj]:
                vis[ni,nj]=True;q.append((ni,nj))
    return vis

def components(a):
    H,W=a.shape; lab=-np.ones_like(a,int); n=0
    for i in range(H):
        for j in range(W):
            if a[i,j]==1 and lab[i,j]<0:
                q=deque([(i,j)]); lab[i,j]=n
                while q:
                    x,y=q.popleft()
                    for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=x+di,y+dj
                        if 0<=nx<H and 0<=ny<W and a[nx,ny]==1 and lab[nx,ny]<0:
                            lab[nx,ny]=n;q.append((nx,ny))
                n+=1
    return lab,n

def transform(g):
    a=np.array(g); H,W=a.shape
    lab,n=components(a)
    out=a.copy()
    enclosed_all=np.zeros_like(a,bool)
    closed_mask=np.zeros_like(a,bool)  # cells belonging to closed comps
    enc_per={}
    for c in range(n):
        walls=lab==c
        vis=flood(a,walls)
        enc=(~vis)&(a==0)
        if enc.any():
            enc_per[c]=enc
            enclosed_all|=enc
            closed_mask|=walls
    # interior: distance from 1-cells of closed comps (4-conn BFS over interior)
    dist=np.full((H,W),10**9)
    q=deque()
    for i in range(H):
        for j in range(W):
            if closed_mask[i,j]:
                dist[i,j]=0;q.append((i,j))
    while q:
        i,j=q.popleft()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<H and 0<=nj<W and dist[ni,nj]>dist[i,j]+1:
                dist[ni,nj]=dist[i,j]+1;q.append((ni,nj))
    for i in range(H):
        for j in range(W):
            if a[i,j]!=0: continue
            if enclosed_all[i,j]:
                out[i,j]= 3 if dist[i,j]%2==1 else 0
            else:
                adj8=any(0<=i+di<H and 0<=j+dj<W and closed_mask[i+di,j+dj] for di in(-1,0,1) for dj in(-1,0,1) if (di,dj)!=(0,0))
                if adj8: out[i,j]=2
    return out.tolist()

